const client = String.raw`
const slides=[...document.querySelectorAll('.slide')];
const notes=document.getElementById('notes');
let current=0,started=null,elapsed=0,ticking=false;
function resize(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1600,innerHeight/900))}
addEventListener('resize',resize);resize();
function show(index){current=Math.max(0,Math.min(slides.length-1,index));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',String(i!==current))});history.replaceState(null,'','#s'+(current+1));document.getElementById('count').textContent=(current+1)+' / '+slides.length;notes.replaceChildren(document.getElementById('note-'+(current+1)).content.cloneNode(true));document.getElementById('prev').disabled=current===0;document.getElementById('next').disabled=current===slides.length-1;}
function toggleNotes(){notes.classList.toggle('open')}
function timer(){if(ticking){elapsed+=Date.now()-started;started=null;ticking=false}else{started=Date.now();ticking=true}document.getElementById('timer').textContent=ticking?'Pause':'Start'}
setInterval(()=>{const used=elapsed+(ticking?Date.now()-started:0);const left=600-Math.floor(used/1000);const abs=Math.abs(left);document.getElementById('clock').textContent=(left<0?'+':'')+String(Math.floor(abs/60))+':'+String(abs%60).padStart(2,'0')},250);
function full(){if(document.fullscreenElement){document.exitFullscreen?.()}else{document.documentElement.requestFullscreen?.().catch(()=>{})}}
document.getElementById('prev').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.getElementById('toggle-notes').onclick=toggleNotes;document.getElementById('timer').onclick=timer;document.getElementById('full').onclick=full;document.getElementById('demo-jump').onclick=()=>show(10);document.getElementById('fallback-button').onclick=()=>document.getElementById('fallback').showModal();
document.querySelectorAll('dialog>button').forEach(b=>b.onclick=()=>b.parentElement.close());
document.querySelectorAll('img[data-zoom]').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','Enlarge: '+img.alt);const open=()=>{const d=document.getElementById('zoom');d.querySelector('img').src=img.src;d.querySelector('img').alt=img.alt;d.querySelector('p').textContent=img.alt;d.showModal()};img.onclick=open;img.onkeydown=e=>{if(e.key==='Enter'){open()}}});
addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.target.closest('button,a')&&['Enter',' '].includes(e.key))return;const k=e.key.toLowerCase();if(['arrowright','arrowdown','pagedown',' '].includes(k)){e.preventDefault();show(current+1)}else if(['arrowleft','arrowup','pageup'].includes(k)){e.preventDefault();show(current-1)}else if(k==='home'){show(0)}else if(k==='end'){show(slides.length-1)}else if(k==='n'){toggleNotes()}else if(k==='t'){timer()}else if(k==='f'){full()}else if(k==='d'){show(10)}else if(k==='b'){document.getElementById('fallback').showModal()}else if(k==='escape'){notes.classList.remove('open')}});
let touchX=null;addEventListener('touchstart',e=>{touchX=e.touches[0].clientX},{passive:true});addEventListener('touchend',e=>{if(touchX===null||document.querySelector('dialog[open]'))return;const dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>60)show(current+(dx<0?1:-1));touchX=null},{passive:true});
addEventListener('hashchange',()=>{const n=Number(location.hash.slice(2));if(Number.isInteger(n)&&n>0)show(n-1)});
show(Math.max(0,(Number(location.hash.match(/^#s(\d+)$/)?.[1])||1)-1));
`;

